  if(j.data&&typeof j.data==='object'){ html=str(j.data.html||j.data.rawHtml||j.data.markdown); }
  else { html=str(j.data||j.body||j.html||j.markdown); }
  if(!html){
    throw new Error('WF11 live parse: no HTML received from the selected transport (Firecrawl/HTTP). The transport is gate-protected (DEC-135): it only runs after live_mode + exact approval token + validated tracked channels + selected transport. Check the transport response/credential; default runs use fixture mode ($0).');
  }
