    if(!idm||!txtm)continue;
    const text=txtm[1].replace(/<br\s*\/?>/gi,' ').replace(/<[^>]+>/g,'').replace(/&amp;/g,'&').replace(/&quot;/g,'"').replace(/&#39;/g,"'").replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/\s+/g,' ').trim();
    if(!text)continue;
    count++;
    out.push({ json: { channel:idm[1], channel_title:titlem?titlem[1].replace(/<[^>]+>/g,'').trim():idm[1], post_id:idm[2], post_url:'https://t.me/'+idm[1]+'/'+idm[2], published_at:timem?timem[1]:'', view_count:viewm?str(viewm[1]):'', text:text } });
  }
